mapper.select:
SELECT id, class_name, teacher_name, description, create_time, update_time, is_deleted FROM tb_class WHERE is_deleted = 0
AND class_name LIKE CONCAT('%', #{className}, '%')
ORDER BY id DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE tb_class
SET class_name   = #{className},
    teacher_name = #{teacherName},
    description  = #{description}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE tb_class
SET is_deleted = 1
WHERE id = #{id}
